sys_script_include.script:
var NeedItUtils = Class.create();
NeedItUtils.prototype = {
    initialize: function() {	
    },
	isDatePast: function(strDate){
    // Create GlideDateTime objects for the current date and the passed in date
    var rightnow = new GlideDateTime();
    var testdatetime = new GlideDateTime(strDate);

    // If the testdate is before rightnow, return true, else return false
    if (testdatetime.before(rightnow)) {
      return true;
    }
    else {
      return false;
    }
  },
  isDateToday: function (strDate){
	// rightnow stores the current date
  var today = new GlideDateTime();
  // Create a GlideDateTime object for the When needed date
  var testdatetime = new GlideDateTime(strDate);

	// if the testdatetime is after the today, return true, else return false 
	if (testdatetime.after(today)) {
      return true;
    }
    else {
      return false;
    }
	},
    type: 'NeedItUtils'
};
